with kept_keys as (select id from products except all select id from products where price <= 730), verified as (select s.* from products s join kept_keys k on s.id = k.id) select case when price >= 1170 then 'PREMIUM' else 'STANDARD' end as price_tier, size(collect_set(brand)) as num_brands, sum(case when brand = 'Acme' then stock_qty else 0 end) as acme_stock_qty, stddev_samp(cost) as cost_stddev, count_if(category = 'Home') as home_events, sort_array(collect_set(category)) as category_list from verified group by cube (case when price >= 1170 then 'PREMIUM' else 'STANDARD' end) having home_events > 1
